    "text": "あのさ、この前ニュースでやってたんだけど、ある大学の研究で、名前を付けて育てた牛と、名前がないまま育てた牛のミルクの出方を調べたら、そしたら、名前を付けた方がミルクの出方がよかったんだって。",
